import * as BABYLON from "@babylonjs/core";

export class ArenaGeometry {
    constructor(private scene: BABYLON.Scene) {}

    public generateElevatorShaft(): void {
        const wallMaterial = new BABYLON.StandardMaterial("wallMat", this.scene);
        wallMaterial.diffuseColor = new BABYLON.Color3(0.07, 0.08, 0.11);
        wallMaterial.specularColor = new BABYLON.Color3(0.05, 0.05, 0.05);

        // Smooth left and right solid walls (boundaries at X = -15 and X = 15)
        const leftWall = BABYLON.MeshBuilder.CreateBox("leftWall", { width: 2, height: 40, depth: 4 }, this.scene);
        leftWall.position.set(-16, 14, 0);
        leftWall.material = wallMaterial;

        const rightWall = BABYLON.MeshBuilder.CreateBox("rightWall", { width: 2, height: 40, depth: 4 }, this.scene);
        rightWall.position.set(16, 14, 0);
        rightWall.material = wallMaterial;

        // Generate unit measurement ticks at regular height intervals
        const tickMat = new BABYLON.StandardMaterial("tickMat", this.scene);
        tickMat.emissiveColor = new BABYLON.Color3(0.2, 0.5, 0.85);
        tickMat.disableLighting = true;

        const tickCount = 18;
        for (let i = 0; i < tickCount; i++) {
            const leftTick = BABYLON.MeshBuilder.CreateBox(`leftTick_${i}`, { width: 0.35, height: 0.08, depth: 2.1 }, this.scene);
            leftTick.position.set(-14.9, i * 2.0, 0);
            leftTick.material = tickMat;
            leftTick.metadata = { type: "scrolling_tick", index: i, initialY: i * 2.0 };

            const rightTick = BABYLON.MeshBuilder.CreateBox(`rightTick_${i}`, { width: 0.35, height: 0.08, depth: 2.1 }, this.scene);
            rightTick.position.set(14.9, i * 2.0, 0);
            rightTick.material = tickMat;
            rightTick.metadata = { type: "scrolling_tick", index: i, initialY: i * 2.0 };
        }
    }
}

src/babylon/particles/JuiceSystem.ts:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { IVisualRegistry } from "../../contracts/IVisualRegistry";
import * as BABYLON from "@babylonjs/core";

interface PooledParticle {
  mesh: BABYLON.Mesh;
  velocity: BABYLON.Vector3;
  lifeRemaining: number;
  maxLife: number;
  active: boolean;
}

export class JuiceSystem implements ISystem {
  readonly phase = SystemPhase.RenderSync;

  private particlePool: PooledParticle[] = [];
  private poolSize = 64;
  private nextPoolIndex = 0;
  private parentNode: BABYLON.TransformNode | null = null;
  private unsubscribes: (() => void)[] = [];

  constructor(
    private broker: EventBroker,
    private visualRegistry: IVisualRegistry
  ) {}

  public init(): void {
    const scene = this.visualRegistry.getScene();
    if (!scene) return;

    this.parentNode = new BABYLON.TransformNode("juiceParticleRoot", scene);

    for (let i = 0; i < this.poolSize; i++) {
      const box = BABYLON.MeshBuilder.CreateBox("juiceParticle_" + i, { size: 0.15 }, scene);
      const mat = new BABYLON.StandardMaterial("juiceParticleMat_" + i, scene);
      mat.emissiveColor = new BABYLON.Color3(1, 1, 1);
      mat.disableLighting = true;
      box.material = mat;
      box.parent = this.parentNode;
      box.setEnabled(false);

      this.particlePool.push({
        mesh: box,
        velocity: new BABYLON.Vector3(),
        lifeRemaining: 0,
        maxLife: 1.0,
        active: false
      });
    }

    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.PLAYER_DAMAGED, () => {
        const scene = this.visualRegistry.getScene();
        if (!scene) return;
        const playerMesh = scene.getMeshByName("playerVisual");
        if (playerMesh) {
          this.spawnBurst(playerMesh.position, new BABYLON.Color3(0.13, 0.77, 0.36), 15);
        }
      })
    );

    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.WARDEN_DAMAGED, () => {
        const scene = this.visualRegistry.getScene();
        if (!scene) return;
        const wardenMesh = scene.getMeshByName("wardenVisual");
        if (wardenMesh) {
          this.spawnBurst(wardenMesh.position, new BABYLON.Color3(0.93, 0.22, 0.22), 20);
        }
      })
    );
  }

  private spawnBurst(position: BABYLON.Vector3, color: BABYLON.Color3, count: number): void {
    for (let i = 0; i < count; i++) {
      const particle = this.particlePool[this.nextPoolIndex];
      particle.mesh.position.copyFrom(position);

      const theta = Math.random() * 2.0 * Math.PI;
      const r = 3.0 + Math.random() * 5.0;
      const vy = 4.0 + Math.random() * 8.0;
      const vz = (Math.random() - 0.5) * 4.0;

      particle.velocity.set(Math.cos(theta) * r, vy, vz);
      particle.lifeRemaining = 0.3 + Math.random() * 0.4;
      particle.maxLife = particle.lifeRemaining;
      particle.active = true;
      particle.mesh.setEnabled(true);

      const mat = particle.mesh.material as BABYLON.StandardMaterial;
      if (mat) {
        mat.emissiveColor.copyFrom(color);
      }

      this.nextPoolIndex = (this.nextPoolIndex + 1) % this.poolSize;
    }
  }

  public update(dt: number): void {
    const gravity = -18.0;
    for (let i = 0; i < this.poolSize; i++) {
      const p = this.particlePool[i];
      if (!p.active) continue;

      p.lifeRemaining -= dt;
      if (p.lifeRemaining <= 0) {
        p.active = false;
        p.mesh.setEnabled(false);
        continue;
      }

      p.velocity.y += gravity * dt;
      p.mesh.position.x += p.velocity.x * dt;
      p.mesh.position.y += p.velocity.y * dt;
      p.mesh.position.z += p.velocity.z * dt;

      const ratio = p.lifeRemaining / p.maxLife;
      p.mesh.scaling.set(ratio, ratio, ratio);
    }
  }

  public dispose(): void {
    this.unsubscribes.forEach(unsub => unsub());
    this.unsubscribes = [];
    if (this.parentNode) {
      this.parentNode.dispose();
    }
    this.particlePool.forEach(p => {
      p.mesh.dispose();
      if (p.mesh.material) p.mesh.material.dispose();
    });
    this.particlePool = [];
  }
}

